using System;using System.Linq;using System.Threading.Tasks;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;
namespace GearLab {
 public sealed class CADValueEditor:TableLayoutPanel {
  readonly Dictionary<string,Control> inputs=new Dictionary<string,Control>();public CADValueEditor(Dictionary<string,string> values){AutoSize=true;Dock=DockStyle.Top;ColumnCount=2;ColumnStyles.Add(new ColumnStyle(SizeType.Percent,55));ColumnStyles.Add(new ColumnStyle(SizeType.Percent,45));foreach(var pair in values){var label=new Label{Text=CADTools.Field(pair.Key),AutoSize=true,Margin=new Padding(4,9,4,4)};Control input;string[] options=pair.Key=="Plane"?new[]{"XY","XZ","YZ"}:pair.Key=="Mode"?new[]{"join","cut","intersect"}:new[]{"Through","Copy","KeepTools"}.Contains(pair.Key)?new[]{"false","true"}:null;if(options!=null){var c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=160};c.Items.AddRange(options);c.SelectedItem=pair.Value;input=c;}else input=new TextBox{Text=pair.Value,Width=160};input.Margin=new Padding(4,6,4,4);input.Dock=DockStyle.Fill;inputs[pair.Key]=input;RowStyles.Add(new RowStyle(SizeType.AutoSize));Controls.Add(label,0,RowCount);Controls.Add(input,1,RowCount);RowCount++;}}
  public void SetValue(string key,string value){inputs[key].Text=value;}
  public Dictionary<string,string> Values(){return inputs.ToDictionary(p=>p.Key,p=>p.Value.Text.Trim());}
 }
 public sealed class CADOperationDialog:Form {
  readonly TextBox name=new TextBox();readonly ComboBox target=new ComboBox(),operation=new ComboBox();readonly CheckedListBox sketches=new CheckedListBox(),tools=new CheckedListBox(),faces=new CheckedListBox(),edges=new CheckedListBox();readonly CADValueEditor values;readonly CADFeature original;readonly TextBox point=new TextBox();readonly Button preview=new Button();public CADFeature Feature;public Func<CADFeature,Task<bool>> Preview;bool previewBusy;
  sealed class Item {public string Id,Text;public override string ToString(){return Text;}}
  public CADOperationDialog(CADDocument doc,CADKernelResult state,CADFeature feature){original=CADDocument.Serializer().Deserialize<CADFeature>(CADDocument.Serializer().Serialize(feature));Text=feature.Name;Font=new Font("Segoe UI",10);Size=new Size(530,820);MinimumSize=new Size(450,500);StartPosition=FormStartPosition.CenterParent;var scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(16)};Controls.Add(scroll);var content=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false};scroll.Controls.Add(content);Action<string,Control> row=(title,c)=>{content.Controls.Add(new Label{Text=title,Width=450,Height=25,Margin=new Padding(0,10,0,0)});c.Width=450;content.Controls.Add(c);};name.Text=feature.Name;row("Название операции",name);
   bool modification=new[]{"fillet","chamfer","shell","draft","hole","presspull","combine","split","move","scale","mirror","linear_pattern","circular_pattern"}.Contains(feature.Kind);
   if(modification||new[]{"extrude","revolve","loft","sweep"}.Contains(feature.Kind)){target.DropDownStyle=ComboBoxStyle.DropDownList;target.Items.Add(new Item{Id=null,Text="Не выбрано"});foreach(var b in state.Bodies??new List<CADBody>())target.Items.Add(new Item{Id=b.Id,Text=CADTools.BodyName(doc,b.Id)});target.SelectedIndex=0;for(int i=0;i<target.Items.Count;i++)if(((Item)target.Items[i]).Id==feature.Target)target.SelectedIndex=i;row("Целевое тело",target);}
   if(new[]{"extrude","revolve","loft","sweep"}.Contains(feature.Kind)){operation.DropDownStyle=ComboBoxStyle.DropDownList;operation.Items.AddRange(new[]{"Новое тело","Объединить","Вырезать","Пересечь"});operation.SelectedIndex=Math.Max(0,Array.IndexOf(new[]{"new","join","cut","intersect"},feature.Operation));row("Результат",operation);sketches.Height=110;foreach(var f in doc.Features.Where(f=>f.Kind=="sketch"&&!f.Suppressed)){int i=sketches.Items.Add(new Item{Id=f.Id,Text=f.Name});sketches.SetItemChecked(i,feature.Sketches.Contains(f.Id));}row(feature.Kind=="sweep"?"Профиль, затем путь (в порядке истории)":"Эскизы / сечения",sketches);}
   if(feature.Kind=="combine"){tools.Height=110;foreach(var b in state.Bodies??new List<CADBody>()){int i=tools.Items.Add(new Item{Id=b.Id,Text=CADTools.BodyName(doc,b.Id)});tools.SetItemChecked(i,feature.Tools.Contains(b.Id));}row("Тела-инструменты",tools);}
   if(new[]{"hole","presspull","shell","draft"}.Contains(feature.Kind)){faces.Height=125;row(feature.Kind=="shell"?"Удаляемые грани":"Грани (выделение из сцены перенесено сюда)",faces);}
   if(new[]{"fillet","chamfer"}.Contains(feature.Kind)){edges.Height=160;row("Рёбра (можно выбрать несколько)",edges);}
   Action fill=()=>{var item=target.SelectedItem as Item;var b=item==null?null:(state.Bodies??new List<CADBody>()).FirstOrDefault(x=>x.Id==item.Id);faces.Items.Clear();edges.Items.Clear();if(b!=null){foreach(var f in b.Faces){int i=faces.Items.Add(f);faces.SetItemChecked(i,feature.Faces.Contains(f.Id));}foreach(var e in b.Edges){int i=edges.Items.Add(e);edges.SetItemChecked(i,feature.Edges.Contains(e.Id));}}};target.SelectedIndexChanged+=(s,e)=>fill();fill();
   values=new CADValueEditor(feature.Values){Width=450};content.Controls.Add(values);if(feature.Kind=="hole"){point.Text=feature.Point==null?"":string.Join("; ",feature.Point.Select(Engine.N));row("Точка на грани: X; Y; Z (пусто — центр грани)",point);}content.Controls.Add(new Label{Text="Размеры принимают формулы: width/2, module*teeth, sqrt(2). Параметры редактируются кнопкой «Параметры».",Width=450,Height=62,ForeColor=Color.SlateGray,Margin=new Padding(0,12,0,0)});
   var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=58,Padding=new Padding(10)};Controls.Add(bottom);preview.Text="Предпросмотр";preview.Width=140;preview.Height=34;preview.Click+=async(s,e)=>{try{if(Preview!=null){previewBusy=true;bottom.Enabled=false;await Preview(Read());}}catch(Exception ex){MessageBox.Show(this,ex.Message);}finally{previewBusy=false;bottom.Enabled=true;}};FormClosing+=(s,e)=>{if(previewBusy)e.Cancel=true;};var apply=new Button{Text="ОК",Width=105,Height=34};apply.Click+=(s,e)=>{try{Feature=Read();DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(this,ex.Message);}};var cancel=new Button{Text="Отмена",Width=105,Height=34,DialogResult=DialogResult.Cancel};bottom.Controls.AddRange(new Control[]{preview,apply,cancel});AcceptButton=apply;CancelButton=cancel;
  }
  CADFeature Read(){var f=CADDocument.Serializer().Deserialize<CADFeature>(CADDocument.Serializer().Serialize(original));f.Name=name.Text.Trim();if(f.Name.Length==0)throw new Exception("Введите название.");f.Values=values.Values();var t=target.SelectedItem as Item;f.Target=t==null?f.Target:t.Id;if(operation.SelectedIndex>=0)f.Operation=new[]{"new","join","cut","intersect"}[operation.SelectedIndex];f.Sketches=sketches.CheckedItems.Cast<Item>().Select(i=>i.Id).ToList();f.Tools=tools.CheckedItems.Cast<Item>().Select(i=>i.Id).Where(id=>id!=f.Target).ToList();f.Faces=faces.CheckedItems.Cast<CADFace>().Select(i=>i.Id).ToList();f.Edges=edges.CheckedItems.Cast<CADEdge>().Select(i=>i.Id).ToList();if(f.Kind=="hole"){if(point.Text.Trim().Length==0)f.Point=null;else{var parts=point.Text.Split(';');if(parts.Length!=3)throw new Exception("Введите X; Y; Z через точку с запятой.");f.Point=parts.Select(x=>{double v;if(!double.TryParse(x.Trim().Replace(',', '.'),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out v))throw new Exception("Неверная координата.");return v;}).ToArray();}}return f;}
 }
 public sealed class CADParametersDialog:Form {
  readonly DataGridView grid=new DataGridView();public Dictionary<string,string> Values;
  public CADParametersDialog(Dictionary<string,string> original){Text="Параметры и формулы";Size=new Size(640,470);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;grid.Dock=DockStyle.Fill;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.Columns.Add("name","Имя");grid.Columns.Add("expression","Выражение / значение в мм");foreach(var p in original)grid.Rows.Add(p.Key,p.Value);Controls.Add(grid);var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=60,Padding=new Padding(10)};var ok=new Button{Text="Применить",Width=130,Height=34};ok.Click+=(s,e)=>{try{grid.EndEdit();Values=new Dictionary<string,string>();foreach(DataGridViewRow row in grid.Rows)if(!row.IsNewRow){string key=Convert.ToString(row.Cells[0].Value).Trim();string val=Convert.ToString(row.Cells[1].Value).Trim();if(key.Length>0)Values.Add(key,val);}DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(this,ex.Message);}};var cancel=new Button{Text="Отмена",Width=110,Height=34,DialogResult=DialogResult.Cancel};bottom.Controls.AddRange(new Control[]{ok,cancel});Controls.Add(bottom);CancelButton=cancel;}
 }
}

